sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
uniform float detail;
half4 effectMain(float2 coord){float2 p=coord*scale;float n=sin(p.x*detail+sin(p.y*detail+phase))+cos(p.y*detail*0.7-phase);float cloud=smoothstep(-0.3,0.9,n);half4 c=image.eval(coord);half3 tint=half3(0.72,0.78,0.86)*half(cloud*amount);return half4(clamp(c.rgb+tint*c.a*0.25,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
